package com.bananalab.lite;
import java.io.*;import java.nio.file.*;import java.util.*;
public final class Stage80PdfCheck{
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 static String fail(byte[] data){try{PdfText.extract(data,new PageStream.Budget());return null;}catch(Exception e){return String.valueOf(e.getMessage());}}
 public static void main(String[] args)throws Exception{Path dir=Paths.get(args[0],"test/resources/pdf");String p1="La fulgorina es un mineral ficticio que se usa para iluminar jardines de prueba.",p2="El señor Ñandú visitó la estación de Quirema en 1954 y midió cuarenta kilómetros.",p3="Tercera página: la deltarina es una sal ficticia que se disuelve en agua tibia.";
  for(String name:new String[]{"estandar.pdf","ascii85.pdf","unicode.pdf","objetos.pdf"}){String text=PdfText.extract(Files.readAllBytes(dir.resolve(name)),new PageStream.Budget());check(text.contains(p1)&&text.contains(p2)&&text.contains(p3),name+": every sentence with its accents: "+text);check(text.indexOf(p1)<text.indexOf(p2)&&text.indexOf(p2)<text.indexOf(p3),name+": reading order across pages");check(text.indexOf("\n\n")>text.indexOf(p2),name+": page break kept");}
  for(String name:new String[]{"unicode.pdf","objetos.pdf"})check(PdfText.extract(Files.readAllBytes(dir.resolve(name)),new PageStream.Budget()).contains("«Comillas», guion — y euro €."),name+": characters outside Latin-1 through the font's own table");
  check(fail(Files.readAllBytes(dir.resolve("cifrado.pdf"))).contains("protegido"),"encrypted file is refused, not guessed");check(fail(Files.readAllBytes(dir.resolve("sin-texto.pdf"))).contains("escaneado"),"page without text is reported");
  check(fail("<html><body>no soy un pdf, pero tengo texto suficiente</body></html>".getBytes("UTF-8")).contains("no es un PDF"),"not a PDF");check(fail("%PDF-1.4\nbasura sin objetos y con texto suficiente para pasar el mínimo".getBytes("UTF-8")).contains("objetos"),"PDF without objects");
  byte[] good=Files.readAllBytes(dir.resolve("estandar.pdf")),cut=Arrays.copyOf(good,good.length/2);String truncated=fail(cut);check(truncated==null||!truncated.isEmpty(),"a truncated file ends with text or a clear error, never a crash");
  Random random=new Random(3);for(int round=0;round<200;round++){byte[] noisy=good.clone();for(int k=0;k<12;k++)noisy[random.nextInt(noisy.length)]=(byte)random.nextInt(256);try{PdfText.extract(noisy,new PageStream.Budget());}catch(IOException expected){}catch(RuntimeException e){throw new AssertionError("corrupted input must fail as IOException, got "+e,e);}}
  check(Arrays.equals(PdfText.ascii85("87cURD]i,\"Ebo80~>".getBytes("UTF-8")),"Hello World!".getBytes("UTF-8"))&&Arrays.equals(PdfText.hex("48 65 6C6c 6F>"),"Hello".getBytes("UTF-8")),"ASCII85 and hex filters");
  String wrapped="Título del documento\nEste párrafo fue cortado por el ancho de la página del documento y sigue en la\nlínea siguiente sin que termine la oración, con una palabra parti-\nda al final del renglón anterior y texto suficiente para medir el ancho.\nUn renglón corto.\nOtro párrafo completo que ocupa todo el ancho disponible de la página impresa\ny termina acá.";String flat=PageReader.unwrap(wrapped);
  check(flat.startsWith("Título del documento\nEste párrafo")&&flat.contains("sigue en la línea siguiente")&&flat.contains("palabra partida al final")&&flat.contains("medir el ancho.\nUn renglón corto.\nOtro párrafo")&&flat.contains("página impresa y termina acá."),"lines of a paragraph are joined, headings and paragraph ends kept: "+flat);
  File tmp=Files.createTempDirectory("pdf70").toFile();try(PageReader.Document d=PageReader.pdfDocument(tmp,"https://example.com/doc.pdf",Files.readAllBytes(dir.resolve("unicode.pdf")),new PageStream.Budget())){check(d.title.startsWith("La fulgorina es un mineral")&&d.url.endsWith("doc.pdf")&&d.links.isEmpty(),"document title from the first line");StringBuilder all=new StringBuilder();try(Reader in=d.reader()){char[] b=new char[4096];int n;while((n=in.read(b))!=-1)all.append(b,0,n);}check(all.toString().contains(p2)&&all.toString().contains("€"),"document text is stored as UTF-8");
   CreatorPersistenceCheck.Fake c=new CreatorPersistenceCheck.Fake();KnowledgeNotebook.rememberReader(c,d.title,d.reader(),d.url,"web");String answer=ReadingKnowledge.answer(NotebookDisk.of(c).selected("que es la deltarina"),"que es la deltarina");check(answer!=null&&answer.contains("sal ficticia")&&answer.contains("https://example.com/doc.pdf"),"a saved PDF is answered with its source: "+answer);}
  String[] left=tmp.list();check(left==null||left.length==0,"temporary files cleaned");check(PageReader.failure("https://example.com/a.pdf",new IOException("El PDF está protegido con contraseña o cifrado; no lo leo")).contains("protegido"),"reader explains PDF errors");
  System.out.println("PASS Stage80 PDF reading: standard and embedded fonts, ASCII85/Flate, object streams, page order, encrypted/scanned/invalid/corrupted files, paragraph unwrapping, storage and answer with source");
 }
}
